using ServiceEntity = Spot.Business.Api.Models.Service;

namespace Spot.Business.Api.Repositories;

/// <summary>
/// Persistence for a business's offered services (the services table). Named "ServiceOffering"
/// rather than "Service" so it doesn't read as a ServiceRepository/ServiceService next to the
/// application-layer services.
/// </summary>
public interface IServiceOfferingRepository
{
    /// <summary>
    /// Inserts <paramref name="service"/>. Its Id, CreatedAt and UpdatedAt are generated by the
    /// database and populated on the entity afterwards. Callers are expected to have already
    /// checked the parent business exists and belongs to the caller.
    /// </summary>
    /// <param name="maxActiveServices">
    /// The most active services the business's plan allows, or null for no limit. Checked with the
    /// business row locked, so two concurrent creates can't both take the last place.
    /// </param>
    /// <exception cref="ServiceLimitReachedException">The business already has that many active services.</exception>
    Task CreateAsync(ServiceEntity service, int? maxActiveServices, CancellationToken ct = default);

    /// <summary>
    /// Loads a service by id as a <b>tracked</b> entity (unlike the read-only lookups), so a caller
    /// can mutate it and persist with <see cref="SaveChangesAsync"/>. Null if none exists.
    /// </summary>
    Task<ServiceEntity?> GetTrackedByIdAsync(Guid serviceId, CancellationToken ct = default);

    /// <summary>
    /// Persists changes made to a tracked service (from <see cref="GetTrackedByIdAsync"/>) and
    /// refreshes it from the database afterwards (<c>updated_at</c> is set by a Postgres trigger).
    /// </summary>
    Task SaveChangesAsync(ServiceEntity service, CancellationToken ct = default);

    /// <summary>
    /// <see cref="SaveChangesAsync"/> for a change that reactivates an inactive service: like
    /// <see cref="CreateAsync"/>, it first checks, with the business row locked, that the business
    /// has fewer than <paramref name="maxActiveServices"/> active services.
    /// </summary>
    /// <exception cref="ServiceLimitReachedException">The business already has that many active services.</exception>
    Task SaveReactivationAsync(ServiceEntity service, int maxActiveServices, CancellationToken ct = default);

    /// <summary>
    /// A page of <paramref name="businessId"/>'s services, ordered by name then id (a stable
    /// tie-breaker, since names aren't unique). <paramref name="active"/> filters by
    /// <c>is_active</c>; <c>null</c> returns both (used for the owner's full view). Callers check
    /// the parent business exists/visible first.
    /// </summary>
    Task<(IReadOnlyList<ServiceEntity> Items, int Total)> ListAsync(
        Guid businessId, int page, int pageSize, bool? active, CancellationToken ct = default);

    /// <summary>Loads a service by id regardless of its active state, or null if none exists.</summary>
    Task<ServiceEntity?> GetByIdAsync(Guid serviceId, CancellationToken ct = default);
}
